=== FILE: rr_arbiter_props.sv ===
// Formal property wrapper for rr_arbiter (interface_spec.md).
// Immediate-assertion style only (if-guarded asserts in always blocks),
// so the open Yosys front end reads it and the cover check can derive
// a cover for every assertion guard.
module rr_arbiter_formal (
    input wire       clk,
    input wire       rst_n,
    input wire [2:0] req
);
    wire [2:0] grant;
    wire [1:0] last;

    rr_arbiter dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant),
        .last  (last)
    );

    // First-cycle guard for $past and for the undefined pre-reset state.
    reg f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Only environment assumption: reset is applied at the first edge
    // (RR-RESET defines the state only from reset). req is unconstrained.
    always @(*)
        if (!f_past_valid)
            assume(!rst_n);

    // Priority order from the specification: last+1, last+2, last (mod 3).
    wire [1:0] p1 = (last == 2'd2) ? 2'd0 : (last + 2'd1);
    wire [1:0] p2 = (last == 2'd0) ? 2'd2 : (last - 2'd1);
    wire [2:0] oh_p1   = 3'b001 << p1;
    wire [2:0] oh_p2   = 3'b001 << p2;
    wire [2:0] oh_last = 3'b001 << last;

    // ---------------- Combinational grant properties ----------------
    always @(*) begin
        if (f_past_valid) begin
            // Port range: last is 0, 1 or 2 (also an induction helper).
            assert(last != 2'd3);

            // RR-IDLE
            if (req == 3'b000)
                assert(grant == 3'b000);

            // RR-PICK, part 1: exactly one grant bit when anyone requests.
            if (req != 3'b000)
                assert((grant != 3'b000) && ((grant & (grant - 3'b001)) == 3'b000));

            // RR-ONLY-REQUESTERS
            assert((grant & ~req) == 3'b000);

            // RR-PICK, part 2: first requester in the priority order wins.
            if (req[p1])
                assert(grant == oh_p1);
            if (!req[p1] && req[p2])
                assert(grant == oh_p2);
            if (!req[p1] && !req[p2] && req[last])
                assert(grant == oh_last);
        end
    end

    // ---------------- Sequential properties ----------------
    always @(posedge clk) begin
        if (f_past_valid) begin
            // RR-RESET
            if (!$past(rst_n))
                assert(last == 2'd2);

            // RR-ROTATE
            if ($past(rst_n) && ($past(grant) != 3'b000))
                assert(oh_last == $past(grant));

            // RR-HOLD
            if ($past(rst_n) && ($past(grant) == 3'b000))
                assert(last == $past(last));

            // RR-YIELD
            if ($past(rst_n) && ($past(grant) != 3'b000)
                    && ((req & ~$past(grant)) != 3'b000))
                assert((grant & $past(grant)) == 3'b000);
        end
    end

    // ---------------- RR-BOUND with per-requester wait counters ----------------
    // w counts consecutive edges (rst_n high) at which requester gi held req
    // high and was not granted.
    genvar gi;
    generate
        for (gi = 0; gi < 3; gi = gi + 1) begin : g_wait
            reg [1:0] w = 2'd0;

            always @(posedge clk) begin
                if (!rst_n || !req[gi] || grant[gi])
                    w <= 2'd0;
                else if (w != 2'd3)
                    w <= w + 2'd1;
            end

            always @(*) begin
                if (f_past_valid) begin
                    // RR-BOUND: at most two grants go to others.
                    assert(w <= 2'd2);
                    // Induction helpers describing the reachable state.
                    if (w != 2'd0)
                        assert(last != gi);
                    if (w == 2'd2)
                        assert(p1 == gi);
                    // RR-BOUND: after two refusals, a held request is granted.
                    if ((w == 2'd2) && req[gi])
                        assert(grant[gi]);
                end
            end

            // Scenario covers: the bound is actually reached and honoured,
            // and each requester is served after rotation.
            always @(posedge clk) begin
                cover(f_past_valid && (w == 2'd2) && req[gi] && grant[gi]);
                cover(f_past_valid && $past(rst_n) && ($past(grant) == (3'b001 << gi))
                      && (last == gi));
            end
        end
    endgenerate

    // ---------------- Scenario covers ----------------
    always @(posedge clk) begin
        // Idle and all-requesting (simultaneous) cases.
        cover(f_past_valid && rst_n && (req == 3'b000));
        cover(f_past_valid && rst_n && (req == 3'b111));
        // Yield: last-served requester loses to another requester.
        cover(f_past_valid && $past(rst_n) && ($past(grant) != 3'b000)
              && ((req & ~$past(grant)) != 3'b000) && ((req & $past(grant)) != 3'b000));
        // Hold: no grant, last unchanged.
        cover(f_past_valid && $past(rst_n) && ($past(grant) == 3'b000));
        // Reset re-applied after running.
        cover(f_past_valid && $past(f_past_valid) && $past(rst_n, 2) && !$past(rst_n)
              && (last == 2'd2));
    end
endmodule
